//! Shared runtime trait identity for `df-derive`.
//!
//! # What this crate provides
//!
//! `df-derive-core` owns the default `dataframe` traits used by the
//! user-facing `df-derive` facade. Sharing these traits across crates lets
//! derived models compose as nested `ToDataFrame` types without each crate
//! inventing a local runtime identity.
//!
//! The [`dataframe`] module exposes:
//!
//! - [`dataframe::Columnar`] — the checked batch-encoding API supplied for
//!   every hidden `ColumnarSpec` implementation generated by the derive.
//! - [`dataframe::ToDataFrame`] — the per-instance and schema API supplied
//!   uniformly from `Columnar`.
//! - [`dataframe::ToDataFrameVec`] — the slice extension trait that routes
//!   `[T]::to_dataframe()` through the known-cardinality encoding path.
//! - [`dataframe::Decimal128Encode`] — the contract for encoding a decimal
//!   value as an `i128` mantissa rescaled to a target scale. The reference
//!   `rust_decimal::Decimal` impl is gated behind the `rust_decimal`
//!   feature (enabled by default).
//! - hidden, runtime-owned exact vector and bitmap storage used by generated
//!   primitive-list encoders.
//! - hidden `ColumnarSpec` support for `()` — the zero-column payload behavior
//!   used by generic `Wrapper<()>` shapes. The blanket implementations supply
//!   `Columnar` and `ToDataFrame`.
//!
//! # When to use this crate
//!
//! Most users get this crate through `df-derive`. Depend on this crate
//! directly when you want the shared traits without the facade, or when you
//! use `df-derive-macros` directly and still want the default runtime
//! identity.
//!
//! ```toml
//! [dependencies]
//! df-derive-core = "0.4"
//! df-derive-macros = "0.4"
//! polars = "0.54"
//! ```
//!
//! Default-runtime generated code uses hidden dependency re-exports from this
//! crate, so direct `polars-arrow` dependencies are not required unless you
//! use a custom runtime.
//!
//! ```ignore
//! use df_derive_core::dataframe::{ToDataFrame as _, ToDataFrameVec as _};
//! use df_derive_macros::ToDataFrame;
//!
//! #[derive(ToDataFrame)]
//! struct Trade { symbol: String, price: f64, size: u64 }
//! ```
//!
//! # Validating a custom decimal backend
//!
//! The `Decimal128Encode` contract requires round-half-to-even (banker's
//! rounding) on scale-down. The reference `rust_decimal::Decimal` impl in
//! this crate honours that contract and is checked against Polars' decimal
//! string-cast behavior in this crate's integration tests.

// `polars` pulls a wide transitive dependency tree (ahash, foldhash,
// hashbrown, windows-sys variants, …) where multiple resolved versions are
// unavoidable. `clippy::multiple_crate_versions` is part of the
// `clippy::cargo` group `just lint` enables, and it would fire ~21 times on
// dependencies entirely outside this crate's control. Allow it here so the
// lint surface stays focused on this crate's own code.
#![allow(clippy::multiple_crate_versions)]

pub mod dataframe {
    use std::sync::Arc;

    use polars::prelude::{
        Column, DataFrame, DataType, PlSmallStr, PolarsResult, Schema, SchemaRef, polars_err,
    };

    #[cfg(feature = "rust_decimal")]
    const DECIMAL128_MAX_SCALE: u32 = 38;

    /// Hidden dependency re-exports used by generated code for the default
    /// dataframe runtime. This is not part of the public API surface.
    #[doc(hidden)]
    pub mod __private {
        pub use polars;
        pub use polars_arrow;

        /// Runtime-owned storage primitives used by generated list encoders.
        ///
        /// Their methods are safe: generated code describes the storage it
        /// has prepared, while this module alone owns the unchecked writes
        /// needed to retain the exact-fill fast path.
        #[doc(hidden)]
        pub mod encode {
            use polars_arrow::bitmap::{Bitmap, MutableBitmap};

            /// Runtime-owned references to source segments and their checked
            /// aggregate element count.
            ///
            /// Private fields make the aggregate count a capability: storage
            /// fillers can validate one complete captured schedule, then
            /// traverse its slices without repeating range checks.
            #[doc(hidden)]
            pub struct CapturedSegments<'source, S> {
                segments: Vec<&'source Vec<S>>,
                len: usize,
            }

            impl<S> Default for CapturedSegments<'_, S> {
                #[inline]
                fn default() -> Self {
                    Self {
                        segments: Vec::new(),
                        len: 0,
                    }
                }
            }

            impl<'source, S> CapturedSegments<'source, S> {
                /// Creates an empty captured schedule.
                #[must_use]
                #[inline]
                pub fn new() -> Self {
                    Self::default()
                }

                /// Creates an empty captured schedule with storage for at
                /// least `capacity` source segments.
                #[must_use]
                #[inline]
                pub fn with_capacity(capacity: usize) -> Self {
                    Self {
                        segments: Vec::with_capacity(capacity),
                        len: 0,
                    }
                }

                /// Records one source slice and returns the new checked total.
                ///
                /// Returns `None` without modifying the schedule if the total
                /// would exceed `usize`.
                #[inline]
                pub fn capture(&mut self, source: &'source Vec<S>) -> Option<usize> {
                    let len = self.len.checked_add(source.len())?;
                    if !source.is_empty() {
                        self.segments.push(source);
                    }
                    self.len = len;
                    Some(len)
                }

                /// Returns the checked aggregate element count.
                #[must_use]
                #[inline]
                #[allow(
                    clippy::len_without_is_empty,
                    reason = "generated exact-storage declarations consume the aggregate count"
                )]
                pub const fn len(&self) -> usize {
                    self.len
                }

                /// Visits captured elements in source-segment order.
                #[allow(
                    clippy::inline_always,
                    reason = "generated view-builder hot loops must inline the visitor"
                )]
                #[inline(always)]
                pub fn visit(&self, mut visit: impl FnMut(&S)) {
                    for segment in &self.segments {
                        for item in *segment {
                            visit(item);
                        }
                    }
                }
            }

            /// Runtime-owned references to penultimate nested-list groups.
            ///
            /// A group contains the innermost `Vec<S>` segments for one list
            /// boundary. Storing one group reference instead of every segment
            /// keeps deep-list schedules compact while the runtime still owns
            /// the checked aggregate leaf count.
            #[doc(hidden)]
            pub struct CapturedSegmentGroups<'source, S> {
                groups: Vec<&'source Vec<Vec<S>>>,
                len: usize,
                segment_count: usize,
            }

            impl<'source, S> CapturedSegmentGroups<'source, S> {
                /// Creates an empty grouped schedule with a source-derived
                /// capacity floor.
                #[must_use]
                #[inline]
                pub fn with_capacity(capacity: usize) -> Self {
                    Self {
                        groups: Vec::with_capacity(capacity),
                        len: 0,
                        segment_count: 0,
                    }
                }

                /// Captures one penultimate group after checking its complete
                /// aggregate leaf and segment counts.
                ///
                /// Returns `None` without modifying the schedule if either
                /// count would exceed `usize` or the leaf count cannot be
                /// represented by Arrow's `i64` list offsets.
                #[inline]
                pub fn capture_group(&mut self, source: &'source Vec<Vec<S>>) -> Option<()> {
                    let segment_count = self.segment_count.checked_add(source.len())?;
                    segment_count.checked_add(1)?;
                    let mut len = self.len;
                    for segment in source {
                        len = len.checked_add(segment.len())?;
                    }
                    i64::try_from(len).ok()?;
                    if !source.is_empty() {
                        self.groups.push(source);
                    }
                    self.len = len;
                    self.segment_count = segment_count;
                    Some(())
                }

                /// Returns the checked aggregate element count.
                #[must_use]
                #[inline]
                #[allow(
                    clippy::len_without_is_empty,
                    reason = "generated exact-storage declarations consume the aggregate count"
                )]
                pub const fn len(&self) -> usize {
                    self.len
                }

                /// Returns the checked number of captured innermost segments.
                #[must_use]
                #[inline]
                pub const fn segment_count(&self) -> usize {
                    self.segment_count
                }

                /// Visits grouped segments in source order and returns their
                /// exact Arrow list offsets.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list hot loops must inline the visitor"
                )]
                #[allow(
                    clippy::cast_possible_wrap,
                    reason = "capture_group proves every immutable leaf-count prefix fits i64"
                )]
                #[inline(always)]
                pub fn visit_segments(&self, mut visit: impl FnMut(&Vec<S>)) -> Vec<i64> {
                    let mut offsets = Vec::with_capacity(self.segment_count + 1);
                    offsets.push(0);
                    let mut len = 0usize;
                    {
                        let mut offset_fill = ExactFillGuard::new(&mut offsets);
                        for group in &self.groups {
                            for segment in *group {
                                visit(segment);
                                // `capture_group` checked the immutable aggregate
                                // before retaining this group, so every prefix is
                                // representable by both `usize` and `i64`.
                                len += segment.len();
                                offset_fill.push(len as i64);
                            }
                        }
                        debug_assert_eq!(offset_fill.len(), self.segment_count + 1);
                    }
                    debug_assert_eq!(len, self.len);
                    offsets
                }
            }

            /// Publishes a partially initialized vector prefix during unwind
            /// without making `Vec::len` part of the successful hot loop.
            struct ExactFillGuard<'values, T> {
                values: &'values mut Vec<T>,
                values_ptr: *mut T,
                initialized: usize,
            }

            impl<'values, T> ExactFillGuard<'values, T> {
                #[inline]
                const fn new(values: &'values mut Vec<T>) -> Self {
                    let initialized = values.len();
                    let values_ptr = values.as_mut_ptr();
                    Self {
                        values,
                        values_ptr,
                        initialized,
                    }
                }

                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned exact-fill hot loops must inline this primitive"
                )]
                #[inline(always)]
                fn push(&mut self, value: T) {
                    debug_assert!(self.initialized < self.values.capacity());
                    // SAFETY: the schedule range is validated before this
                    // guard is created. Each call writes the next position,
                    // and `Drop` publishes precisely the initialized prefix.
                    unsafe {
                        self.values_ptr.add(self.initialized).write(value);
                    }
                    self.initialized += 1;
                }

                #[inline]
                const fn len(&self) -> usize {
                    self.initialized
                }
            }

            impl<T> Drop for ExactFillGuard<'_, T> {
                #[inline]
                fn drop(&mut self) {
                    // SAFETY: `push` initialized every position between the
                    // vector's original length and `initialized` exactly once.
                    unsafe { self.values.set_len(self.initialized) };
                }
            }

            /// Keeps prepared bitmap progress local and publishes the cursor
            /// during unwind or successful scope exit.
            struct PreparedBitmapFillGuard<'bitmap> {
                bitmap: &'bitmap mut MutableBitmap,
                published: &'bitmap mut usize,
                cursor: usize,
            }

            impl<'bitmap> PreparedBitmapFillGuard<'bitmap> {
                #[inline]
                const fn new(
                    bitmap: &'bitmap mut MutableBitmap,
                    published: &'bitmap mut usize,
                ) -> Self {
                    let cursor = *published;
                    Self {
                        bitmap,
                        published,
                        cursor,
                    }
                }

                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned prepared-bitmap hot loops must inline this primitive"
                )]
                #[inline(always)]
                fn commit_validity(&mut self, is_valid: bool) {
                    debug_assert!(self.cursor < self.bitmap.len());
                    if !is_valid {
                        // SAFETY: the complete schedule range was prepared
                        // before this guard was created.
                        unsafe { self.bitmap.set_unchecked(self.cursor, false) };
                    }
                    self.cursor += 1;
                }

                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned prepared-bitmap hot loops must inline this primitive"
                )]
                #[inline(always)]
                fn commit_boolean(&mut self, value: bool) {
                    debug_assert!(self.cursor < self.bitmap.len());
                    if value {
                        // SAFETY: the complete schedule range was prepared
                        // before this guard was created.
                        unsafe { self.bitmap.set_unchecked(self.cursor, true) };
                    }
                    self.cursor += 1;
                }

                #[inline]
                const fn len(&self) -> usize {
                    self.cursor
                }
            }

            impl Drop for PreparedBitmapFillGuard<'_> {
                #[inline]
                fn drop(&mut self) {
                    *self.published = self.cursor;
                }
            }

            /// Fills native values and validity with one shared cursor.
            struct NullableExactFillGuard<'storage, T> {
                values: &'storage mut Vec<T>,
                values_ptr: *mut T,
                validity: &'storage mut MutableBitmap,
                validity_published: &'storage mut usize,
                cursor: usize,
            }

            impl<'storage, T> NullableExactFillGuard<'storage, T> {
                #[inline]
                fn new(
                    values: &'storage mut Vec<T>,
                    validity: &'storage mut MutableBitmap,
                    validity_published: &'storage mut usize,
                ) -> Self {
                    let cursor = values.len();
                    debug_assert_eq!(cursor, *validity_published);
                    let values_ptr = values.as_mut_ptr();
                    Self {
                        values,
                        values_ptr,
                        validity,
                        validity_published,
                        cursor,
                    }
                }

                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned nullable exact-fill hot loops must inline this primitive"
                )]
                #[inline(always)]
                fn push(&mut self, value: T, is_valid: bool) {
                    debug_assert!(self.cursor < self.values.capacity());
                    debug_assert!(self.cursor < self.validity.len());
                    // SAFETY: both complete ranges were validated before this
                    // guard was created, and `cursor` advances once per pair.
                    unsafe {
                        self.values_ptr.add(self.cursor).write(value);
                        if !is_valid {
                            self.validity.set_unchecked(self.cursor, false);
                        }
                    }
                    self.cursor += 1;
                }

                #[inline]
                const fn len(&self) -> usize {
                    self.cursor
                }
            }

            impl<T> Drop for NullableExactFillGuard<'_, T> {
                #[inline]
                fn drop(&mut self) {
                    // SAFETY: every position below `cursor` was initialized
                    // exactly once by `push`.
                    unsafe { self.values.set_len(self.cursor) };
                    *self.validity_published = self.cursor;
                }
            }

            /// Fills Boolean values and validity with one shared cursor.
            struct NullableBooleanFillGuard<'storage> {
                values: &'storage mut MutableBitmap,
                values_published: &'storage mut usize,
                validity: &'storage mut MutableBitmap,
                validity_published: &'storage mut usize,
                cursor: usize,
            }

            impl<'storage> NullableBooleanFillGuard<'storage> {
                #[inline]
                fn new(
                    values: &'storage mut MutableBitmap,
                    values_published: &'storage mut usize,
                    validity: &'storage mut MutableBitmap,
                    validity_published: &'storage mut usize,
                ) -> Self {
                    let cursor = *values_published;
                    debug_assert_eq!(cursor, *validity_published);
                    Self {
                        values,
                        values_published,
                        validity,
                        validity_published,
                        cursor,
                    }
                }

                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned nullable Boolean hot loops must inline this primitive"
                )]
                #[inline(always)]
                fn push(&mut self, value: bool, is_valid: bool) {
                    debug_assert!(self.cursor < self.values.len());
                    debug_assert!(self.cursor < self.validity.len());
                    // SAFETY: both complete bitmap ranges were validated
                    // before this guard was created.
                    unsafe {
                        if value {
                            self.values.set_unchecked(self.cursor, true);
                        }
                        if !is_valid {
                            self.validity.set_unchecked(self.cursor, false);
                        }
                    }
                    self.cursor += 1;
                }

                #[inline]
                const fn len(&self) -> usize {
                    self.cursor
                }
            }

            impl Drop for NullableBooleanFillGuard<'_> {
                #[inline]
                fn drop(&mut self) {
                    *self.values_published = self.cursor;
                    *self.validity_published = self.cursor;
                }
            }

            /// A vector filled from source slices through runtime-owned loops.
            ///
            /// Each public fill checks or acquires the complete destination
            /// range once. The runtime can then initialize that range without
            /// repeating a capacity check for every element. Exact buffers
            /// additionally verify their final initialized length when
            /// consumed.
            #[doc(hidden)]
            pub struct ExactBuffer<T> {
                values: Vec<T>,
                exact_len: Option<usize>,
            }

            impl<T> ExactBuffer<T> {
                /// Allocates an incrementally growing buffer.
                #[must_use]
                #[inline]
                pub fn with_capacity(capacity: usize) -> Self {
                    Self {
                        values: Vec::with_capacity(capacity),
                        exact_len: None,
                    }
                }

                /// Allocates storage for exactly `len` initialized values.
                #[must_use]
                #[inline]
                pub fn with_exact_len(len: usize) -> Self {
                    Self {
                        values: Vec::with_capacity(len),
                        exact_len: Some(len),
                    }
                }

                #[inline]
                fn prepare_segment(&mut self, additional: usize) -> usize {
                    let end = self
                        .values
                        .len()
                        .checked_add(additional)
                        .expect("df-derive: exact buffer length overflow");
                    if let Some(exact_len) = self.exact_len {
                        assert!(
                            end <= exact_len,
                            "df-derive: exact buffer segment exceeded its declared length",
                        );
                    } else {
                        self.values.reserve(additional);
                    }
                    end
                }

                /// Initializes one position in a range proven by
                /// `prepare_segment`.
                ///
                /// # Safety
                ///
                /// The caller must have reserved or validated the position at
                /// `self.values.len()` and must call this at most once for each
                /// source element in that proven range.
                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned generated hot loops must inline this primitive"
                )]
                #[inline(always)]
                unsafe fn push_prepared(&mut self, value: T) {
                    let initialized = self.values.len();
                    debug_assert!(initialized < self.values.capacity());
                    // SAFETY: upheld by the caller. The value is written
                    // before the vector length advances, so unwinding from a
                    // later mapper invocation drops the complete initialized
                    // prefix exactly once.
                    unsafe {
                        self.values.as_mut_ptr().add(initialized).write(value);
                        self.values.set_len(initialized + 1);
                    }
                }

                /// Extends this buffer from one trusted-cardinality source
                /// segment after validating its whole destination range.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the segment would overflow
                /// `usize` or an exact buffer's declared length.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_segment<S>(&mut self, source: &[S], mut map: impl FnMut(&S) -> T) {
                    let end = self.prepare_segment(source.len());
                    for item in source {
                        let value = map(item);
                        // SAFETY: `prepare_segment` proved the complete source
                        // range, and this loop writes exactly once per item.
                        unsafe { self.push_prepared(value) };
                    }
                    debug_assert_eq!(self.values.len(), end);
                }

                /// Extends this buffer from a runtime-owned captured schedule
                /// after validating its aggregate destination range once.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the aggregate range exceeds
                /// an exact buffer's declared length.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_captured<S>(
                    &mut self,
                    source: &CapturedSegments<'_, S>,
                    mut map: impl FnMut(&S) -> T,
                ) {
                    let end = self.prepare_segment(source.len);
                    let mut fill = ExactFillGuard::new(&mut self.values);
                    for segment in &source.segments {
                        for item in *segment {
                            let value = map(item);
                            fill.push(value);
                        }
                    }
                    debug_assert_eq!(fill.len(), end);
                }

                /// Copies representation-identical values from a captured
                /// schedule without routing each element through a mapper.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list copy loops must inline across the runtime boundary"
                )]
                #[inline(always)]
                pub fn extend_copied_captured(&mut self, source: &CapturedSegments<'_, T>)
                where
                    T: Copy,
                {
                    let end = self.prepare_segment(source.len);
                    for segment in &source.segments {
                        for item in *segment {
                            // SAFETY: `prepare_segment` proved the complete
                            // captured range, and each source item is copied
                            // exactly once.
                            unsafe { self.push_prepared(*item) };
                        }
                    }
                    debug_assert_eq!(self.values.len(), end);
                }

                /// Extends this buffer from a compact grouped schedule after
                /// validating its aggregate destination range once.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_grouped<S>(
                    &mut self,
                    source: &CapturedSegmentGroups<'_, S>,
                    mut map: impl FnMut(&S) -> T,
                ) -> Vec<i64> {
                    let end = self.prepare_segment(source.len);
                    let mut fill = ExactFillGuard::new(&mut self.values);
                    let offsets = source.visit_segments(|segment| {
                        for item in segment {
                            fill.push(map(item));
                        }
                    });
                    debug_assert_eq!(fill.len(), end);
                    offsets
                }

                /// Copies representation-identical values from a compact
                /// grouped schedule and constructs its exact Arrow offsets.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list copy loops must inline across the runtime boundary"
                )]
                #[allow(
                    clippy::cast_possible_wrap,
                    reason = "capture_group proves every immutable leaf-count prefix fits i64"
                )]
                #[inline(always)]
                pub fn extend_copied_grouped(
                    &mut self,
                    source: &CapturedSegmentGroups<'_, T>,
                ) -> Vec<i64>
                where
                    T: Copy,
                {
                    let end = self.prepare_segment(source.len);
                    let mut offsets = Vec::with_capacity(source.segment_count + 1);
                    offsets.push(0);
                    let mut len = 0usize;
                    for group in &source.groups {
                        for segment in *group {
                            for item in segment {
                                // SAFETY: `prepare_segment` proved the complete
                                // grouped range, and each source item is copied
                                // exactly once.
                                unsafe { self.push_prepared(*item) };
                            }
                            len += segment.len();
                            offsets.push(len as i64);
                        }
                    }
                    debug_assert_eq!(offsets.len(), source.segment_count + 1);
                    debug_assert_eq!(self.values.len(), end);
                    debug_assert_eq!(len, source.len);
                    offsets
                }

                /// Fallible counterpart to [`Self::extend_segment`].
                ///
                /// Successfully mapped values remain owned by the initialized
                /// prefix if `map` returns an error.
                ///
                /// # Errors
                ///
                /// Returns the first mapper error without evaluating later
                /// source values.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the segment would overflow
                /// `usize` or an exact buffer's declared length.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn try_extend_segment<S, E>(
                    &mut self,
                    source: &[S],
                    mut map: impl FnMut(&S) -> Result<T, E>,
                ) -> Result<(), E> {
                    let end = self.prepare_segment(source.len());
                    for item in source {
                        let value = map(item)?;
                        // SAFETY: `prepare_segment` proved the complete source
                        // range, and this loop writes at most once per item.
                        unsafe { self.push_prepared(value) };
                    }
                    debug_assert_eq!(self.values.len(), end);
                    Ok(())
                }

                /// Extends paired native values and validity from a nullable
                /// source segment.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if either destination range is
                /// inconsistent, overflows `usize`, or exceeds an exact
                /// declaration.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_nullable_segment<S>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &[S],
                    mut map: impl FnMut(&S) -> (T, bool),
                ) {
                    let start = self.values.len();
                    let end = self.prepare_segment(source.len());
                    validity.prepare_segment(start, source.len());
                    for item in source {
                        let index = self.values.len();
                        let (value, is_valid) = map(item);
                        // SAFETY: both complete ranges were proved before the
                        // mapper ran, and this loop advances them in lockstep.
                        unsafe {
                            self.push_prepared(value);
                            validity.commit_prepared(index, is_valid);
                        }
                    }
                    debug_assert_eq!(self.values.len(), end);
                }

                /// Extends paired values and validity from one captured
                /// schedule after validating both aggregate ranges once.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if either aggregate range is
                /// inconsistent or exceeds an exact declaration.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_nullable_captured<S>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &CapturedSegments<'_, S>,
                    mut map: impl FnMut(&S) -> Option<T>,
                ) where
                    T: Default,
                {
                    let start = self.values.len();
                    let end = self.prepare_segment(source.len);
                    validity.prepare_segment(start, source.len);
                    let mut fill = NullableExactFillGuard::new(
                        &mut self.values,
                        &mut validity.bitmap,
                        &mut validity.initialized,
                    );
                    for segment in &source.segments {
                        for item in *segment {
                            match map(item) {
                                Some(value) => fill.push(value, true),
                                None => fill.push(T::default(), false),
                            }
                        }
                    }
                    debug_assert_eq!(fill.len(), end);
                }

                /// Extends paired values and validity from captured native
                /// options without an element mapper.
                #[allow(
                    clippy::inline_always,
                    reason = "generated nullable primitive-list loops must inline across the runtime boundary"
                )]
                #[inline(always)]
                pub fn extend_nullable_options_captured(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &CapturedSegments<'_, Option<T>>,
                ) where
                    T: Copy + Default,
                {
                    let start = self.values.len();
                    let end = self.prepare_segment(source.len);
                    validity.prepare_segment(start, source.len);
                    for segment in &source.segments {
                        for item in *segment {
                            let index = self.values.len();
                            let (value, is_valid) = match item {
                                Some(value) => (*value, true),
                                None => (T::default(), false),
                            };
                            // SAFETY: both aggregate ranges were proved before
                            // the loop and advance once per source item.
                            unsafe {
                                self.push_prepared(value);
                                validity.commit_prepared(index, is_valid);
                            }
                        }
                    }
                    debug_assert_eq!(self.values.len(), end);
                }

                /// Extends paired values and validity from a compact grouped
                /// schedule after validating both aggregate ranges once.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list hot loops must inline the mapper"
                )]
                #[allow(
                    clippy::cast_possible_wrap,
                    reason = "capture_group proves every immutable leaf-count prefix fits i64"
                )]
                #[inline(always)]
                pub fn extend_nullable_grouped<S>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &CapturedSegmentGroups<'_, S>,
                    mut map: impl FnMut(&S) -> Option<T>,
                ) -> Vec<i64>
                where
                    T: Default,
                {
                    let start = self.values.len();
                    let end = self.prepare_segment(source.len);
                    validity.prepare_segment(start, source.len);
                    let mut fill = NullableExactFillGuard::new(
                        &mut self.values,
                        &mut validity.bitmap,
                        &mut validity.initialized,
                    );
                    // Keep value, validity, and offset cursors in this one
                    // loop. Routing the nullable path through the generic
                    // segment visitor forces materially worse code generation.
                    let mut offsets = Vec::with_capacity(source.segment_count + 1);
                    offsets.push(0);
                    let mut len = 0usize;
                    {
                        let mut offset_fill = ExactFillGuard::new(&mut offsets);
                        for group in &source.groups {
                            for segment in *group {
                                for item in segment {
                                    match map(item) {
                                        Some(value) => fill.push(value, true),
                                        None => fill.push(T::default(), false),
                                    }
                                }
                                len += segment.len();
                                offset_fill.push(len as i64);
                            }
                        }
                        debug_assert_eq!(offset_fill.len(), source.segment_count + 1);
                    }
                    debug_assert_eq!(fill.len(), end);
                    debug_assert_eq!(len, source.len);
                    offsets
                }

                /// Extends paired values and validity from grouped native
                /// options without an element mapper.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped nullable loops must inline across the runtime boundary"
                )]
                #[allow(
                    clippy::cast_possible_wrap,
                    reason = "capture_group proves every immutable leaf-count prefix fits i64"
                )]
                #[inline(always)]
                pub fn extend_nullable_options_grouped(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &CapturedSegmentGroups<'_, Option<T>>,
                ) -> Vec<i64>
                where
                    T: Copy + Default,
                {
                    let start = self.values.len();
                    let end = self.prepare_segment(source.len);
                    validity.prepare_segment(start, source.len);
                    let mut offsets = Vec::with_capacity(source.segment_count + 1);
                    offsets.push(0);
                    let mut len = 0usize;
                    for group in &source.groups {
                        for segment in *group {
                            for item in segment {
                                let index = self.values.len();
                                let (value, is_valid) = match item {
                                    Some(value) => (*value, true),
                                    None => (T::default(), false),
                                };
                                // SAFETY: both aggregate ranges were proved
                                // before the loop and advance once per item.
                                unsafe {
                                    self.push_prepared(value);
                                    validity.commit_prepared(index, is_valid);
                                }
                            }
                            len += segment.len();
                            offsets.push(len as i64);
                        }
                    }
                    debug_assert_eq!(offsets.len(), source.segment_count + 1);
                    debug_assert_eq!(self.values.len(), end);
                    debug_assert_eq!(len, source.len);
                    offsets
                }

                /// Fallible counterpart to
                /// [`Self::extend_nullable_segment`].
                ///
                /// # Errors
                ///
                /// Returns the first mapper error without evaluating later
                /// source values.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if either destination range is
                /// inconsistent, overflows `usize`, or exceeds an exact
                /// declaration.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn try_extend_nullable_segment<S, E>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &[S],
                    mut map: impl FnMut(&S) -> Result<(T, bool), E>,
                ) -> Result<(), E> {
                    let start = self.values.len();
                    let end = self.prepare_segment(source.len());
                    validity.prepare_segment(start, source.len());
                    for item in source {
                        let index = self.values.len();
                        let (value, is_valid) = map(item)?;
                        // SAFETY: both complete ranges were proved before the
                        // mapper ran, and this loop advances them in lockstep.
                        unsafe {
                            self.push_prepared(value);
                            validity.commit_prepared(index, is_valid);
                        }
                    }
                    debug_assert_eq!(self.values.len(), end);
                    Ok(())
                }

                /// Returns the initialized element count.
                #[must_use]
                #[inline]
                #[allow(
                    clippy::len_without_is_empty,
                    reason = "the hidden generated-code contract only consumes the initialized count"
                )]
                pub const fn len(&self) -> usize {
                    self.values.len()
                }

                /// Returns the initialized values after checking exact-fill
                /// invariants.
                ///
                /// # Panics
                ///
                /// Panics if an exact buffer's final length differs from its
                /// declared length.
                #[must_use]
                #[inline]
                pub fn finish(self) -> Vec<T> {
                    if let Some(exact_len) = self.exact_len {
                        assert_eq!(
                            self.values.len(),
                            exact_len,
                            "df-derive: exact buffer was not completely initialized",
                        );
                    }
                    self.values
                }
            }

            /// An all-valid bitmap whose prepared positions can be patched to
            /// null without exposing unchecked bitmap mutation.
            #[doc(hidden)]
            pub struct PreparedValidity {
                bitmap: MutableBitmap,
                initialized: usize,
                exact_len: Option<usize>,
                growth_floor: usize,
            }

            impl PreparedValidity {
                /// Allocates an initially empty, incrementally prepared
                /// validity bitmap.
                #[must_use]
                #[inline]
                pub fn with_capacity(capacity: usize) -> Self {
                    Self {
                        bitmap: MutableBitmap::with_capacity(capacity),
                        initialized: 0,
                        exact_len: None,
                        growth_floor: capacity,
                    }
                }

                /// Creates an all-valid bitmap with an exact final length.
                #[must_use]
                #[inline]
                pub fn with_exact_len(len: usize) -> Self {
                    Self {
                        bitmap: MutableBitmap::from_len_set(len),
                        initialized: 0,
                        exact_len: Some(len),
                        growth_floor: 0,
                    }
                }

                #[inline]
                fn prepare_segment(&mut self, values_len: usize, additional: usize) -> usize {
                    assert_eq!(
                        values_len, self.initialized,
                        "df-derive: validity segment did not start at its initialized endpoint",
                    );
                    let end = self
                        .initialized
                        .checked_add(additional)
                        .expect("df-derive: validity bitmap length overflow");
                    if let Some(exact_len) = self.exact_len {
                        assert!(
                            end <= exact_len,
                            "df-derive: validity segment exceeded its declared length",
                        );
                    } else if self.bitmap.len() < end {
                        let missing = end - self.bitmap.len();
                        let growth = self.bitmap.len().max(self.growth_floor).max(additional);
                        let available = usize::MAX - self.bitmap.len();
                        self.bitmap
                            .extend_constant(missing.max(growth).min(available), true);
                    }
                    end
                }

                /// Commits one result inside a range proved by
                /// `prepare_segment`.
                ///
                /// # Safety
                ///
                /// `index` must equal the initialized cursor and must lie in
                /// the range most recently proved by `prepare_segment`.
                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned generated hot loops must inline this primitive"
                )]
                #[inline(always)]
                unsafe fn commit_prepared(&mut self, index: usize, is_valid: bool) {
                    debug_assert_eq!(index, self.initialized);
                    debug_assert!(index < self.bitmap.len());
                    if !is_valid {
                        // SAFETY: upheld by the caller.
                        unsafe { self.bitmap.set_unchecked(index, false) };
                    }
                    self.initialized += 1;
                }

                /// Drives an external value builder over one source segment
                /// while preparing and patching its paired validity range.
                ///
                /// The mapper must append exactly one external value and
                /// return whether that value is valid. Finalization checks the
                /// external builder's observed length.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the segment start or range
                /// is invalid.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_segment<S>(
                    &mut self,
                    values_len: usize,
                    source: &[S],
                    mut map: impl FnMut(&S) -> bool,
                ) {
                    let end = self.prepare_segment(values_len, source.len());
                    for item in source {
                        let index = self.initialized;
                        let is_valid = map(item);
                        // SAFETY: `prepare_segment` proved the complete range,
                        // and the mapper has completed this external value.
                        unsafe { self.commit_prepared(index, is_valid) };
                    }
                    debug_assert_eq!(self.initialized, end);
                }

                /// Drives an external value builder over a captured schedule
                /// after validating its aggregate validity range once.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the schedule start or
                /// aggregate range is invalid.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_captured<S>(
                    &mut self,
                    values_len: usize,
                    source: &CapturedSegments<'_, S>,
                    mut map: impl FnMut(&S) -> bool,
                ) {
                    let end = self.prepare_segment(values_len, source.len);
                    let mut fill =
                        PreparedBitmapFillGuard::new(&mut self.bitmap, &mut self.initialized);
                    for segment in &source.segments {
                        for item in *segment {
                            let is_valid = map(item);
                            fill.commit_validity(is_valid);
                        }
                    }
                    debug_assert_eq!(fill.len(), end);
                }

                /// Drives an external value builder over a compact grouped
                /// schedule after validating its aggregate validity range.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_grouped<S>(
                    &mut self,
                    values_len: usize,
                    source: &CapturedSegmentGroups<'_, S>,
                    mut map: impl FnMut(&S) -> bool,
                ) -> Vec<i64> {
                    let end = self.prepare_segment(values_len, source.len);
                    let mut fill =
                        PreparedBitmapFillGuard::new(&mut self.bitmap, &mut self.initialized);
                    let offsets = source.visit_segments(|segment| {
                        for item in segment {
                            fill.commit_validity(map(item));
                        }
                    });
                    debug_assert_eq!(fill.len(), end);
                    offsets
                }

                /// Fallible counterpart to [`Self::extend_segment`].
                ///
                /// # Errors
                ///
                /// Returns the first mapper error without evaluating later
                /// source values.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the segment start or range
                /// is invalid.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn try_extend_segment<S, E>(
                    &mut self,
                    values_len: usize,
                    source: &[S],
                    mut map: impl FnMut(&S) -> Result<bool, E>,
                ) -> Result<(), E> {
                    let end = self.prepare_segment(values_len, source.len());
                    for item in source {
                        let index = self.initialized;
                        let is_valid = map(item)?;
                        // SAFETY: `prepare_segment` proved the complete range,
                        // and the mapper has completed this external value.
                        unsafe { self.commit_prepared(index, is_valid) };
                    }
                    debug_assert_eq!(self.initialized, end);
                    Ok(())
                }

                /// Returns the prepared bitmap after checking it against the
                /// observed value count and trimming amortized backing bits.
                ///
                /// # Panics
                ///
                /// Panics if `actual_len` differs from the initialized cursor
                /// or an exact bitmap's declared length.
                #[must_use]
                #[inline]
                pub fn finish(mut self, actual_len: usize) -> Option<Bitmap> {
                    assert_eq!(
                        actual_len, self.initialized,
                        "df-derive: validity length did not match initialized values",
                    );
                    if let Some(exact_len) = self.exact_len {
                        assert_eq!(
                            self.initialized, exact_len,
                            "df-derive: validity bitmap was not completely initialized",
                        );
                    }
                    self.bitmap.resize(actual_len, true);
                    self.bitmap.into()
                }
            }

            /// A zeroed Boolean value bitmap filled through an owned cursor
            /// without exposing unchecked bitmap mutation.
            #[doc(hidden)]
            pub struct PreparedBooleanValues {
                bitmap: MutableBitmap,
                initialized: usize,
            }

            impl PreparedBooleanValues {
                /// Creates a zeroed bitmap with an exact final length.
                #[must_use]
                #[inline]
                pub fn with_exact_len(len: usize) -> Self {
                    Self {
                        bitmap: MutableBitmap::from_len_zeroed(len),
                        initialized: 0,
                    }
                }

                #[inline]
                fn prepare_segment(&self, additional: usize) -> usize {
                    let end = self
                        .initialized
                        .checked_add(additional)
                        .expect("df-derive: Boolean bitmap length overflow");
                    assert!(
                        end <= self.bitmap.len(),
                        "df-derive: Boolean segment exceeded its declared length",
                    );
                    end
                }

                /// Commits one Boolean in a range proved by
                /// `prepare_segment`.
                ///
                /// # Safety
                ///
                /// The initialized cursor must lie in the range most recently
                /// proved by `prepare_segment`.
                #[allow(
                    clippy::inline_always,
                    reason = "runtime-owned generated hot loops must inline this primitive"
                )]
                #[inline(always)]
                unsafe fn commit_prepared(&mut self, value: bool) {
                    debug_assert!(self.initialized < self.bitmap.len());
                    if value {
                        // SAFETY: upheld by the caller.
                        unsafe { self.bitmap.set_unchecked(self.initialized, true) };
                    }
                    self.initialized += 1;
                }

                /// Extends this bitmap from one trusted-cardinality source
                /// segment after checking the whole destination range.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the segment overflows or
                /// exceeds the declared bitmap length.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_segment<S>(&mut self, source: &[S], mut map: impl FnMut(&S) -> bool) {
                    let end = self.prepare_segment(source.len());
                    for item in source {
                        let value = map(item);
                        // SAFETY: `prepare_segment` proved the complete range,
                        // and this loop commits exactly once per source item.
                        unsafe { self.commit_prepared(value) };
                    }
                    debug_assert_eq!(self.initialized, end);
                }

                /// Extends this bitmap from a captured schedule after checking
                /// its aggregate destination range once.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if the aggregate range exceeds
                /// the declared bitmap length.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_captured<S>(
                    &mut self,
                    source: &CapturedSegments<'_, S>,
                    mut map: impl FnMut(&S) -> bool,
                ) {
                    let end = self.prepare_segment(source.len);
                    let mut fill =
                        PreparedBitmapFillGuard::new(&mut self.bitmap, &mut self.initialized);
                    for segment in &source.segments {
                        for item in *segment {
                            let value = map(item);
                            fill.commit_boolean(value);
                        }
                    }
                    debug_assert_eq!(fill.len(), end);
                }

                /// Extends this bitmap from a compact grouped schedule after
                /// validating its aggregate destination range once.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_grouped<S>(
                    &mut self,
                    source: &CapturedSegmentGroups<'_, S>,
                    mut map: impl FnMut(&S) -> bool,
                ) -> Vec<i64> {
                    let end = self.prepare_segment(source.len);
                    let mut fill =
                        PreparedBitmapFillGuard::new(&mut self.bitmap, &mut self.initialized);
                    let offsets = source.visit_segments(|segment| {
                        for item in segment {
                            fill.commit_boolean(map(item));
                        }
                    });
                    debug_assert_eq!(fill.len(), end);
                    offsets
                }

                /// Extends paired Boolean values and validity from one
                /// nullable source segment.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if either destination range is
                /// inconsistent, overflows, or exceeds its declaration.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_nullable_segment<S>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &[S],
                    mut map: impl FnMut(&S) -> (bool, bool),
                ) {
                    let start = self.initialized;
                    let end = self.prepare_segment(source.len());
                    validity.prepare_segment(start, source.len());
                    for item in source {
                        let index = self.initialized;
                        let (value, is_valid) = map(item);
                        // SAFETY: both complete ranges were proved before the
                        // mapper ran, and this loop advances them in lockstep.
                        unsafe {
                            self.commit_prepared(value);
                            validity.commit_prepared(index, is_valid);
                        }
                    }
                    debug_assert_eq!(self.initialized, end);
                }

                /// Extends paired Boolean values and validity from one
                /// captured schedule after validating both aggregate ranges.
                ///
                /// # Panics
                ///
                /// Panics before invoking `map` if either aggregate range is
                /// inconsistent or exceeds its declaration.
                #[allow(
                    clippy::inline_always,
                    reason = "generated primitive-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_nullable_captured<S>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &CapturedSegments<'_, S>,
                    mut map: impl FnMut(&S) -> Option<bool>,
                ) {
                    let start = self.initialized;
                    let end = self.prepare_segment(source.len);
                    validity.prepare_segment(start, source.len);
                    let mut fill = NullableBooleanFillGuard::new(
                        &mut self.bitmap,
                        &mut self.initialized,
                        &mut validity.bitmap,
                        &mut validity.initialized,
                    );
                    for segment in &source.segments {
                        for item in *segment {
                            match map(item) {
                                Some(value) => fill.push(value, true),
                                None => fill.push(false, false),
                            }
                        }
                    }
                    debug_assert_eq!(fill.len(), end);
                }

                /// Extends paired Boolean values and validity from a compact
                /// grouped schedule after validating both aggregate ranges.
                #[allow(
                    clippy::inline_always,
                    reason = "generated grouped-list hot loops must inline the mapper"
                )]
                #[inline(always)]
                pub fn extend_nullable_grouped<S>(
                    &mut self,
                    validity: &mut PreparedValidity,
                    source: &CapturedSegmentGroups<'_, S>,
                    mut map: impl FnMut(&S) -> Option<bool>,
                ) -> Vec<i64> {
                    let start = self.initialized;
                    let end = self.prepare_segment(source.len);
                    validity.prepare_segment(start, source.len);
                    let mut fill = NullableBooleanFillGuard::new(
                        &mut self.bitmap,
                        &mut self.initialized,
                        &mut validity.bitmap,
                        &mut validity.initialized,
                    );
                    let offsets = source.visit_segments(|segment| {
                        for item in segment {
                            match map(item) {
                                Some(value) => fill.push(value, true),
                                None => fill.push(false, false),
                            }
                        }
                    });
                    debug_assert_eq!(fill.len(), end);
                    offsets
                }

                /// Returns the prepared value count.
                #[must_use]
                #[inline]
                #[allow(
                    clippy::len_without_is_empty,
                    reason = "the hidden generated-code contract only consumes the initialized count"
                )]
                pub const fn len(&self) -> usize {
                    self.initialized
                }

                /// Returns the immutable value bitmap after checking length.
                ///
                /// # Panics
                ///
                /// Panics if any exact position remains uninitialized.
                #[must_use]
                #[inline]
                pub fn finish(self) -> Bitmap {
                    assert_eq!(
                        self.initialized,
                        self.bitmap.len(),
                        "df-derive: prepared Boolean values were not completely initialized",
                    );
                    self.bitmap.into()
                }
            }

            #[cfg(test)]
            mod tests {
                use std::cell::Cell;
                use std::rc::Rc;

                use super::*;

                struct DropCounter(Rc<Cell<usize>>);

                impl Drop for DropCounter {
                    fn drop(&mut self) {
                        self.0.set(self.0.get() + 1);
                    }
                }

                #[test]
                fn exact_storage_supports_empty_and_zero_sized_values() {
                    assert!(ExactBuffer::<()>::with_exact_len(0).finish().is_empty());

                    let mut values = ExactBuffer::with_exact_len(3);
                    values.extend_segment(&[(), (), ()], |()| ());
                    assert_eq!(values.finish().len(), 3);

                    assert!(PreparedValidity::with_exact_len(0).finish(0).is_none());
                    assert_eq!(PreparedBooleanValues::with_exact_len(0).finish().len(), 0);
                }

                #[test]
                fn exact_buffer_finishes_fully_initialized_storage() {
                    let mut values = ExactBuffer::with_exact_len(3);
                    values.extend_segment(&[1, 2, 3], |value| value * 10);

                    assert_eq!(values.len(), 3);
                    assert_eq!(values.finish(), [10, 20, 30]);
                }

                #[test]
                fn captured_schedule_fills_after_one_aggregate_check() {
                    let first = vec![10, 20];
                    let second = vec![30, 40];
                    let mut captured = CapturedSegments::new();
                    assert_eq!(captured.capture(&first), Some(2));
                    assert_eq!(captured.capture(&second), Some(4));
                    let mut values = ExactBuffer::with_exact_len(4);
                    values.extend_captured(&captured, |value| *value);

                    assert_eq!(values.finish(), [10, 20, 30, 40]);
                }

                #[test]
                fn captured_schedule_rejects_total_overflow_without_mutation() {
                    let source = vec![1];
                    let mut captured = CapturedSegments::<u8> {
                        segments: Vec::new(),
                        len: usize::MAX,
                    };
                    assert_eq!(captured.capture(&source), None);
                    assert_eq!(captured.len(), usize::MAX);
                    assert!(captured.segments.is_empty());
                }

                #[test]
                fn grouped_schedule_preserves_empty_segment_offsets() {
                    let empty_group: Vec<Vec<i32>> = Vec::new();
                    let group = vec![vec![], vec![10, 20], vec![]];
                    let mut captured = CapturedSegmentGroups::with_capacity(2);
                    assert_eq!(captured.capture_group(&empty_group), Some(()));
                    assert_eq!(captured.capture_group(&group), Some(()));
                    assert_eq!(captured.len(), 2);
                    assert_eq!(captured.segment_count(), 3);

                    let mut values = ExactBuffer::with_exact_len(2);
                    let offsets = values.extend_grouped(&captured, |value| *value);

                    assert_eq!(offsets, [0, 0, 2, 2]);
                    assert_eq!(values.finish(), [10, 20]);
                }

                #[test]
                fn grouped_schedule_rejects_overflow_atomically() {
                    let group = vec![vec![1u8]];
                    let mut leaf_overflow = CapturedSegmentGroups {
                        groups: Vec::new(),
                        len: usize::MAX,
                        segment_count: 0,
                    };
                    assert_eq!(leaf_overflow.capture_group(&group), None);
                    assert_eq!(leaf_overflow.len(), usize::MAX);
                    assert_eq!(leaf_overflow.segment_count(), 0);
                    assert!(leaf_overflow.groups.is_empty());

                    let empty_segment = vec![Vec::<u8>::new()];
                    let mut segment_overflow = CapturedSegmentGroups {
                        groups: Vec::new(),
                        len: 0,
                        segment_count: usize::MAX,
                    };
                    assert_eq!(segment_overflow.capture_group(&empty_segment), None);
                    assert_eq!(segment_overflow.len(), 0);
                    assert_eq!(segment_overflow.segment_count(), usize::MAX);
                    assert!(segment_overflow.groups.is_empty());
                }

                #[test]
                fn grouped_exact_fill_drops_mapper_panic_prefix_once() {
                    let drops = Rc::new(Cell::new(0));
                    let group = vec![vec![0, 1], vec![2]];
                    let mut captured = CapturedSegmentGroups::with_capacity(1);
                    assert_eq!(captured.capture_group(&group), Some(()));
                    let mut values = ExactBuffer::with_exact_len(3);

                    let panic = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        drop(values.extend_grouped(&captured, |value| {
                            assert_ne!(*value, 1, "mapper panic");
                            DropCounter(Rc::clone(&drops))
                        }));
                    }));
                    assert!(panic.is_err());
                    assert_eq!(values.len(), 1);
                    assert_eq!(drops.get(), 0, "the completed prefix remains vector-owned");

                    drop(values);
                    assert_eq!(drops.get(), 1, "the initialized prefix is dropped once");
                }

                #[test]
                fn grouped_nullable_panic_keeps_values_and_validity_synchronized() {
                    let group = vec![vec![Some(10), None], vec![Some(30)]];
                    let mut captured = CapturedSegmentGroups::with_capacity(1);
                    assert_eq!(captured.capture_group(&group), Some(()));
                    let mut values = ExactBuffer::with_exact_len(3);
                    let mut validity = PreparedValidity::with_exact_len(3);

                    let panic = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        drop(
                            values.extend_nullable_grouped(&mut validity, &captured, |value| {
                                assert_ne!(*value, Some(30), "mapper panic");
                                *value
                            }),
                        );
                    }));
                    assert!(panic.is_err());
                    assert_eq!(values.len(), 2);
                    assert_eq!(validity.initialized, 2);
                    assert!(validity.bitmap.get(0));
                    assert!(!validity.bitmap.get(1));
                }

                #[test]
                fn incremental_buffer_grows_for_each_observed_segment() {
                    let mut values = ExactBuffer::with_capacity(0);
                    values.extend_segment(&[10, 20], |value| *value);
                    values.extend_segment(&[30], |value| *value);

                    assert_eq!(values.finish(), [10, 20, 30]);
                }

                #[test]
                fn exact_buffer_rejects_overfill_before_invoking_mapper() {
                    let calls = Cell::new(0);
                    let mut values = ExactBuffer::with_exact_len(1);
                    values.extend_segment(&[10], |value| *value);

                    let overflow = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        values.extend_segment(&[20], |value| {
                            calls.set(calls.get() + 1);
                            *value
                        });
                    }));
                    assert!(overflow.is_err());
                    assert_eq!(calls.get(), 0);
                }

                #[test]
                #[should_panic(expected = "exact buffer was not completely initialized")]
                fn exact_buffer_rejects_underfill() {
                    let mut values = ExactBuffer::with_exact_len(2);
                    values.extend_segment(&[10], |value| *value);
                    drop(values.finish());
                }

                #[test]
                #[should_panic(expected = "exact buffer length overflow")]
                fn exact_buffer_checks_length_arithmetic_before_reserving() {
                    let mut values = ExactBuffer::with_exact_len(1);
                    values.extend_segment(&[()], |()| ());
                    values.prepare_segment(usize::MAX);
                }

                #[test]
                fn exact_buffer_drops_mapper_panic_prefix_once() {
                    let drops = Rc::new(Cell::new(0));
                    let mut values = ExactBuffer::with_exact_len(3);
                    let panic = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        values.extend_segment(&[0, 1, 2], |value| {
                            assert_ne!(*value, 1, "mapper panic");
                            DropCounter(Rc::clone(&drops))
                        });
                    }));
                    assert!(panic.is_err());
                    assert_eq!(drops.get(), 0, "the completed prefix remains vector-owned");

                    drop(values);
                    assert_eq!(drops.get(), 1, "the initialized prefix is dropped once");
                }

                #[test]
                fn exact_buffer_drops_fallible_mapper_prefix_once() {
                    let drops = Rc::new(Cell::new(0));
                    let mut values = ExactBuffer::with_exact_len(3);
                    let result: Result<(), ()> = values.try_extend_segment(&[0, 1, 2], |value| {
                        if *value == 2 {
                            Err(())
                        } else {
                            Ok(DropCounter(Rc::clone(&drops)))
                        }
                    });
                    assert!(result.is_err());

                    drop(values);
                    assert_eq!(drops.get(), 2);
                }

                #[test]
                fn nullable_numeric_segments_fill_values_and_validity_together() {
                    let source = [Some(10), None, Some(30)];
                    let mut values = ExactBuffer::with_exact_len(source.len());
                    let mut validity = PreparedValidity::with_exact_len(source.len());
                    values.extend_nullable_segment(&mut validity, &source, |value| {
                        value.map_or((0, false), |value| (value, true))
                    });

                    let validity = validity
                        .finish(values.len())
                        .expect("one null retains validity");
                    assert_eq!(values.finish(), [10, 0, 30]);
                    assert!(validity.get_bit(0));
                    assert!(!validity.get_bit(1));
                    assert!(validity.get_bit(2));
                }

                #[test]
                fn prepared_bitmaps_patch_positions_across_machine_words() {
                    let true_positions = [0, 63, 64, 127, 128];
                    let null_positions = [1, 62, 65, 126, 129];
                    let source: Vec<Option<bool>> = (0..130)
                        .map(|index| {
                            (!null_positions.contains(&index))
                                .then(|| true_positions.contains(&index))
                        })
                        .collect();
                    let mut values = PreparedBooleanValues::with_exact_len(130);
                    let mut validity = PreparedValidity::with_exact_len(130);
                    values.extend_nullable_segment(&mut validity, &source, |value| {
                        value.map_or((false, false), |value| (value, true))
                    });

                    let values = values.finish();
                    let validity = validity.finish(130);
                    let validity = validity.expect("null patches retain validity");
                    for index in true_positions {
                        assert!(values.get_bit(index), "value bit {index}");
                    }
                    for index in null_positions {
                        assert!(!validity.get_bit(index), "validity bit {index}");
                    }
                }

                #[test]
                fn streamed_validity_trims_amortized_backing_to_observed_values() {
                    let source = [Some(10), None, Some(30)];
                    let mut external_values = Vec::new();
                    let mut validity = PreparedValidity::with_capacity(64);
                    validity.extend_segment(external_values.len(), &source, |value| {
                        external_values.push(value.unwrap_or_default());
                        value.is_some()
                    });

                    let validity = validity.finish(external_values.len());
                    let validity = validity.expect("null patch retains validity");
                    assert_eq!(validity.len(), 3);
                    assert!(validity.get_bit(0));
                    assert!(!validity.get_bit(1));
                    assert!(validity.get_bit(2));
                }

                #[test]
                fn streamed_validity_rejects_wrong_start_before_invoking_mapper() {
                    let calls = Cell::new(0);
                    let mut validity = PreparedValidity::with_capacity(4);
                    let mismatch = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        validity.extend_segment(1, &[true], |_| {
                            calls.set(calls.get() + 1);
                            true
                        });
                    }));
                    assert!(mismatch.is_err());
                    assert_eq!(calls.get(), 0);
                }

                #[test]
                #[should_panic(expected = "validity bitmap length overflow")]
                fn prepared_validity_checks_length_arithmetic_before_growing() {
                    let mut validity = PreparedValidity::with_exact_len(1);
                    validity.extend_segment(0, &[true], |_| true);
                    validity.prepare_segment(1, usize::MAX);
                }

                #[test]
                fn fallible_external_validity_stops_at_error_prefix() {
                    let mut external_values = Vec::new();
                    let mut validity = PreparedValidity::with_capacity(3);
                    let result: Result<(), ()> =
                        validity.try_extend_segment(0, &[0, 1, 2], |value| {
                            if *value == 1 {
                                Err(())
                            } else {
                                external_values.push(*value);
                                Ok(true)
                            }
                        });
                    assert!(result.is_err());
                    assert_eq!(external_values, [0]);
                    assert!(validity.finish(external_values.len()).is_none());
                }

                #[test]
                #[should_panic(expected = "validity bitmap was not completely initialized")]
                fn prepared_validity_rejects_exact_underfill() {
                    let validity = PreparedValidity::with_exact_len(2);
                    drop(validity.finish(0));
                }

                #[test]
                fn prepared_boolean_values_reject_overfill_before_invoking_mapper() {
                    let calls = Cell::new(0);
                    let mut values = PreparedBooleanValues::with_exact_len(1);
                    values.extend_segment(&[true], |value| *value);
                    let overflow = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        values.extend_segment(&[false], |value| {
                            calls.set(calls.get() + 1);
                            *value
                        });
                    }));
                    assert!(overflow.is_err());
                    assert_eq!(calls.get(), 0);
                }

                #[test]
                #[should_panic(expected = "were not completely initialized")]
                fn prepared_boolean_values_reject_underfill() {
                    let mut values = PreparedBooleanValues::with_exact_len(2);
                    values.extend_segment(&[true], |value| *value);
                    drop(values.finish());
                }
            }
        }
    }

    /// A schema-checked column batch produced by [`Columnar::encode_batch`].
    ///
    /// Its fields are private so only [`ColumnSink`] can construct a batch
    /// after validating schema width, ordered names, data types, and height.
    #[doc(hidden)]
    pub struct EncodedBatch {
        height: usize,
        columns: Vec<Column>,
    }

    impl EncodedBatch {
        /// Consumes the batch and returns its validated columns in schema
        /// order.
        #[doc(hidden)]
        #[must_use]
        pub fn into_columns(self) -> Vec<Column> {
            self.columns
        }

        /// Consumes the batch and constructs its public `DataFrame` boundary.
        #[doc(hidden)]
        #[must_use]
        fn into_dataframe(self) -> DataFrame {
            // SAFETY: `EncodedBatch` has private fields and is constructed
            // only by `ColumnSink::finish`. The sink accepts columns only in
            // the schema's unique name order, and `finish` verifies that
            // every column length equals `height`.
            unsafe { DataFrame::new_unchecked(self.height, self.columns) }
        }
    }

    /// Schema-bound destination used by hidden column encoders.
    ///
    /// The sink checks every column as it is appended. Finalization additionally
    /// checks that no declared column is missing and every column has the row
    /// count observed at the iterator boundary. Construction and finalization
    /// stay private so a `ColumnarSpec` cannot replace its assigned sink with
    /// one bound to a different schema.
    #[doc(hidden)]
    pub struct ColumnSink {
        schema: SchemaRef,
        columns: Vec<Column>,
        producer: &'static str,
    }

    /// The next schema position reserved for one output column.
    ///
    /// A slot borrows its sink until it is either committed or dropped. A
    /// failed commit leaves the sink at the same schema position, so an
    /// encoder cannot accidentally skip a declared column.
    #[doc(hidden)]
    #[must_use]
    pub struct ColumnSlot<'a> {
        columns: &'a mut Vec<Column>,
        producer: &'static str,
        index: usize,
        expected_name: &'a PlSmallStr,
        expected_dtype: &'a DataType,
    }

    impl ColumnSlot<'_> {
        /// Returns the schema-authoritative name for this output position.
        #[must_use]
        #[inline]
        pub const fn name(&self) -> &PlSmallStr {
            self.expected_name
        }

        /// Returns the schema-authoritative data type for this output position.
        #[must_use]
        #[inline]
        pub const fn dtype(&self) -> &DataType {
            self.expected_dtype
        }

        /// Commits a column after validating it against this schema position.
        ///
        /// # Errors
        ///
        /// Returns an error for a name or data-type mismatch. The sink is not
        /// advanced when validation fails.
        #[inline]
        pub fn commit(self, column: Column) -> PolarsResult<()> {
            if column.name() != self.expected_name {
                return Err(polars_err!(
                    ComputeError:
                    "df-derive: ColumnarSpec for {} returned column `{}` at index {}, expected `{}`",
                    self.producer,
                    column.name(),
                    self.index,
                    self.expected_name,
                ));
            }
            if column.dtype() != self.expected_dtype {
                return Err(polars_err!(
                    ComputeError:
                    "df-derive: ColumnarSpec for {} returned dtype {:?} for column `{}` at index {}, expected {:?}",
                    self.producer,
                    column.dtype(),
                    column.name(),
                    self.index,
                    self.expected_dtype,
                ));
            }

            self.columns.push(column);
            Ok(())
        }
    }

    impl ColumnSink {
        /// Creates an empty sink for `schema`.
        #[must_use]
        fn new(schema: SchemaRef, producer: &'static str) -> Self {
            let columns = Vec::with_capacity(schema.len());
            Self {
                schema,
                columns,
                producer,
            }
        }

        /// Reserves the next declared output position.
        ///
        /// # Errors
        ///
        /// Returns an error when every declared schema position already has a
        /// committed column.
        #[inline]
        pub fn next_slot(&mut self) -> PolarsResult<ColumnSlot<'_>> {
            let Self {
                schema,
                columns,
                producer,
            } = self;
            let producer = *producer;
            let index = columns.len();
            let Some((expected_name, expected_dtype)) = schema.get_at_index(index) else {
                return Err(polars_err!(
                    ComputeError:
                    "df-derive: ColumnarSpec for {} requested column slot at index {}, exceeding schema width {}",
                    producer,
                    index,
                    schema.len(),
                ));
            };
            Ok(ColumnSlot {
                columns,
                producer,
                index,
                expected_name,
                expected_dtype,
            })
        }

        /// Finalizes the sink against the actual number of yielded rows.
        ///
        /// # Errors
        ///
        /// Returns an error if a declared column is missing or any column has
        /// a height different from `height`.
        fn finish(self, height: usize) -> PolarsResult<EncodedBatch> {
            if self.columns.len() != self.schema.len() {
                return Err(polars_err!(
                    ComputeError:
                    "df-derive: ColumnarSpec for {} returned schema width {}, expected {}",
                    self.producer,
                    self.columns.len(),
                    self.schema.len(),
                ));
            }

            for (index, column) in self.columns.iter().enumerate() {
                if column.len() != height {
                    return Err(polars_err!(
                        ComputeError:
                        "df-derive: ColumnarSpec for {} returned height {} for column `{}` at index {}, expected {}",
                        self.producer,
                        column.len(),
                        column.name(),
                        index,
                        height,
                    ));
                }
            }

            Ok(EncodedBatch {
                height,
                columns: self.columns,
            })
        }
    }

    /// Iterator boundary understood by generated encoders that may need to
    /// revisit already yielded row references.
    ///
    /// General iterators that need replay use a dedicated cursor that captures
    /// references as it advances. Slice-backed cursors can replay their yielded
    /// prefix directly without allocating a second reference buffer.
    ///
    /// Implementations must report the exact number of items successfully
    /// returned by `Iterator::next`. After `enable_replay` returns,
    /// `replay` must yield exactly those successful source items once each and
    /// in source order. Runtime-owned storage validates generated fill counts,
    /// so violating this semantic contract can produce an encoding error or
    /// panic but cannot make generated code memory-unsafe.
    #[doc(hidden)]
    pub trait RowCursor: Iterator {
        /// A fresh iterator over the rows yielded so far, in source order.
        type Replay<'cursor>: Iterator<Item = Self::Item>
        where
            Self: 'cursor;

        /// Enables replay before the first source row is requested.
        ///
        /// `capacity` is the lower bound already observed by generated code;
        /// implementations must not query `size_hint` again.
        fn enable_replay(&mut self, capacity: usize);

        /// Returns a fresh iterator over the rows yielded since replay was
        /// enabled.
        fn replay(&self) -> Self::Replay<'_>;

        /// Returns the number of rows yielded from the source cursor.
        fn yielded(&self) -> usize;
    }

    struct StreamingCursor<I>
    where
        I: Iterator,
    {
        inner: I,
        yielded: usize,
    }

    impl<I> StreamingCursor<I>
    where
        I: Iterator,
    {
        #[inline]
        const fn new(inner: I) -> Self {
            Self { inner, yielded: 0 }
        }
    }

    impl<I> Iterator for StreamingCursor<I>
    where
        I: Iterator,
        I::Item: Copy,
    {
        type Item = I::Item;

        #[inline]
        fn next(&mut self) -> Option<Self::Item> {
            let item = self.inner.next()?;
            self.yielded += 1;
            Some(item)
        }

        #[inline]
        fn size_hint(&self) -> (usize, Option<usize>) {
            self.inner.size_hint()
        }
    }

    impl<I> RowCursor for StreamingCursor<I>
    where
        I: Iterator,
        I::Item: Copy,
    {
        type Replay<'cursor>
            = std::iter::Empty<I::Item>
        where
            Self: 'cursor;

        #[cold]
        #[inline(never)]
        fn enable_replay(&mut self, _capacity: usize) {
            panic!("df-derive: compact streaming cursor does not support row replay");
        }

        #[inline]
        fn replay(&self) -> Self::Replay<'_> {
            std::iter::empty()
        }

        #[inline]
        fn yielded(&self) -> usize {
            self.yielded
        }
    }

    struct ReplayStreamingCursor<I>
    where
        I: Iterator,
    {
        inner: I,
        yielded: usize,
        replay: Option<Vec<I::Item>>,
    }

    impl<I> ReplayStreamingCursor<I>
    where
        I: Iterator,
    {
        #[inline]
        const fn new(inner: I) -> Self {
            Self {
                inner,
                yielded: 0,
                replay: None,
            }
        }
    }

    impl<I> Iterator for ReplayStreamingCursor<I>
    where
        I: Iterator,
        I::Item: Copy,
    {
        type Item = I::Item;

        #[inline]
        fn next(&mut self) -> Option<Self::Item> {
            let item = self.inner.next()?;
            match &mut self.replay {
                Some(replay) => replay.push(item),
                None => self.yielded += 1,
            }
            Some(item)
        }

        #[inline]
        fn size_hint(&self) -> (usize, Option<usize>) {
            self.inner.size_hint()
        }
    }

    impl<I> RowCursor for ReplayStreamingCursor<I>
    where
        I: Iterator,
        I::Item: Copy,
    {
        type Replay<'cursor>
            = std::iter::Copied<std::slice::Iter<'cursor, I::Item>>
        where
            Self: 'cursor;

        #[inline]
        fn enable_replay(&mut self, capacity: usize) {
            assert!(
                self.yielded == 0 && self.replay.is_none(),
                "df-derive: row replay must be enabled before iteration",
            );
            self.replay = Some(Vec::with_capacity(capacity));
        }

        #[inline]
        fn replay(&self) -> Self::Replay<'_> {
            self.replay
                .as_ref()
                .expect("df-derive: row replay requested before it was enabled")
                .iter()
                .copied()
        }

        #[inline]
        fn yielded(&self) -> usize {
            self.replay.as_ref().map_or(self.yielded, Vec::len)
        }
    }

    struct SliceCursor<'row, T> {
        original: &'row [T],
        remaining: std::slice::Iter<'row, T>,
    }

    impl<'row, T> SliceCursor<'row, T> {
        #[inline]
        fn new(rows: &'row [T]) -> Self {
            Self {
                original: rows,
                remaining: rows.iter(),
            }
        }
    }

    impl<'row, T> Iterator for SliceCursor<'row, T> {
        type Item = &'row T;

        #[inline]
        fn next(&mut self) -> Option<Self::Item> {
            self.remaining.next()
        }

        #[inline]
        fn size_hint(&self) -> (usize, Option<usize>) {
            self.remaining.size_hint()
        }
    }

    impl<'row, T> RowCursor for SliceCursor<'row, T> {
        type Replay<'cursor>
            = std::slice::Iter<'row, T>
        where
            Self: 'cursor;

        #[inline]
        fn enable_replay(&mut self, _capacity: usize) {}

        #[inline]
        fn replay(&self) -> Self::Replay<'_> {
            let original: &'row [T] = self.original;
            original[..self.yielded()].iter()
        }

        #[inline]
        fn yielded(&self) -> usize {
            self.original.len() - self.remaining.len()
        }
    }

    struct RefSliceCursor<'slice, 'row, T> {
        original: &'slice [&'row T],
        remaining: std::iter::Copied<std::slice::Iter<'slice, &'row T>>,
    }

    impl<'slice, 'row, T> RefSliceCursor<'slice, 'row, T> {
        #[inline]
        fn new(rows: &'slice [&'row T]) -> Self {
            Self {
                original: rows,
                remaining: rows.iter().copied(),
            }
        }
    }

    impl<'row, T> Iterator for RefSliceCursor<'_, 'row, T> {
        type Item = &'row T;

        #[inline]
        fn next(&mut self) -> Option<Self::Item> {
            self.remaining.next()
        }

        #[inline]
        fn size_hint(&self) -> (usize, Option<usize>) {
            self.remaining.size_hint()
        }
    }

    impl<'slice, 'row, T> RowCursor for RefSliceCursor<'slice, 'row, T> {
        type Replay<'cursor>
            = std::iter::Copied<std::slice::Iter<'slice, &'row T>>
        where
            Self: 'cursor;

        #[inline]
        fn enable_replay(&mut self, _capacity: usize) {}

        #[inline]
        fn replay(&self) -> Self::Replay<'_> {
            let original: &'slice [&'row T] = self.original;
            original[..self.yielded()].iter().copied()
        }

        #[inline]
        fn yielded(&self) -> usize {
            self.original.len() - self.remaining.len()
        }
    }

    /// Low-level schema and column implementation surface populated by the
    /// derive macro.
    ///
    /// Callers should use [`Columnar::encode`] for iterator inputs or
    /// [`ToDataFrameVec::to_dataframe`] for slices. The checked boundaries
    /// determine actual height by counting yielded iterator rows or using the
    /// slice cardinality, then validate this implementation's output through
    /// [`ColumnSink`].
    ///
    /// # Implementor contract
    ///
    /// `build_schema` must be value-independent and stable across calls.
    /// `encode_columns` must always emit exactly that ordered schema. The
    /// `encode_columns` must acquire each schema position through
    /// [`ColumnSink::next_slot`] and commit it through [`ColumnSlot::commit`].
    /// The checked boundary enforces width, order, names, data types, and
    /// actual row height for each individual batch; it cannot prove that separate
    /// calls to `build_schema` return the same declaration.
    #[doc(hidden)]
    pub trait ColumnarSpec: Sized {
        /// Whether general iterator inputs require buffered row replay.
        #[doc(hidden)]
        const REQUIRES_ROW_REPLAY: bool = false;

        /// Builds this type's complete ordered schema without encoding rows.
        ///
        /// # Errors
        ///
        /// Returns an error if schema composition fails.
        fn build_schema() -> PolarsResult<SchemaRef>;

        /// Appends this type's encoded columns to `sink`.
        ///
        /// # Errors
        ///
        /// Returns an error if value encoding or sink validation fails.
        fn encode_columns<'a, I>(rows: &mut I, sink: &mut ColumnSink) -> PolarsResult<()>
        where
            Self: 'a,
            I: RowCursor<Item = &'a Self>;
    }

    #[allow(
        clippy::inline_always,
        reason = "the cursor type must specialize away before entering generated row loops"
    )]
    #[inline(always)]
    fn encode_streaming_cursor<'row, T, C>(
        mut rows: C,
        sink: &mut ColumnSink,
    ) -> PolarsResult<usize>
    where
        T: ColumnarSpec + 'row,
        C: RowCursor<Item = &'row T>,
    {
        T::encode_columns(&mut rows, sink)?;
        rows.by_ref().for_each(drop);
        Ok(rows.yielded())
    }

    /// Checked columnar batch API supplied for every [`ColumnarSpec`].
    pub trait Columnar: ColumnarSpec {
        /// Encodes references from one owned iterator into a validated batch.
        ///
        /// The low-level encoder may consume any prefix. After it succeeds,
        /// this boundary drains the iterator once so height always comes from
        /// the actual yielded row count. If low-level encoding fails, the error
        /// is returned immediately without evaluating the iterator's remainder.
        ///
        /// # Errors
        ///
        /// Returns an error if schema construction, value encoding, or batch
        /// validation fails.
        #[doc(hidden)]
        fn encode_batch<'a, R>(rows: R) -> PolarsResult<EncodedBatch>
        where
            Self: 'a,
            R: IntoIterator<Item = &'a Self>,
        {
            let schema = <Self as ColumnarSpec>::build_schema()?;
            let mut sink = ColumnSink::new(schema, std::any::type_name::<Self>());
            let rows = rows.into_iter();
            let height = if <Self as ColumnarSpec>::REQUIRES_ROW_REPLAY {
                encode_streaming_cursor::<Self, _>(ReplayStreamingCursor::new(rows), &mut sink)?
            } else {
                encode_streaming_cursor::<Self, _>(StreamingCursor::new(rows), &mut sink)?
            };

            sink.finish(height)
        }

        /// Encodes a slice without counting rows that already have a known
        /// cardinality.
        ///
        /// # Errors
        ///
        /// Returns an error if schema construction, value encoding, or batch
        /// validation fails.
        #[doc(hidden)]
        fn encode_slice(rows: &[Self]) -> PolarsResult<EncodedBatch> {
            let schema = <Self as ColumnarSpec>::build_schema()?;
            let mut sink = ColumnSink::new(schema, std::any::type_name::<Self>());
            let mut row_iter = SliceCursor::new(rows);

            <Self as ColumnarSpec>::encode_columns(&mut row_iter, &mut sink)?;

            sink.finish(rows.len())
        }

        /// Encodes a slice of row references without allocating another
        /// reference buffer when generated child encoders need replay.
        ///
        /// # Errors
        ///
        /// Returns an error if schema construction, value encoding, or batch
        /// validation fails.
        #[doc(hidden)]
        fn encode_ref_batch<'row>(rows: &[&'row Self]) -> PolarsResult<EncodedBatch>
        where
            Self: 'row,
        {
            let schema = <Self as ColumnarSpec>::build_schema()?;
            let mut sink = ColumnSink::new(schema, std::any::type_name::<Self>());
            let mut row_iter = RefSliceCursor::new(rows);

            <Self as ColumnarSpec>::encode_columns(&mut row_iter, &mut sink)?;
            row_iter.by_ref().for_each(drop);

            sink.finish(rows.len())
        }

        /// Encodes references from a general iterator into a public
        /// `DataFrame`, counting the rows actually yielded.
        ///
        /// For a slice or `Vec<Self>`, prefer [`ToDataFrameVec::to_dataframe`]
        /// so the known row count can be used directly.
        ///
        /// # Errors
        ///
        /// Returns an error if schema composition, value encoding, or batch
        /// validation fails.
        #[inline]
        fn encode<'a, R>(rows: R) -> PolarsResult<DataFrame>
        where
            Self: 'a,
            R: IntoIterator<Item = &'a Self>,
        {
            Ok(Self::encode_batch(rows)?.into_dataframe())
        }
    }

    impl<T: ColumnarSpec> Columnar for T {}

    /// Per-instance and schema convenience API supplied for every [`Columnar`]
    /// implementation.
    pub trait ToDataFrame: Columnar {
        /// # Errors
        /// Returns an error if schema composition, value encoding, or batch
        /// validation fails.
        #[inline]
        fn to_dataframe(&self) -> PolarsResult<DataFrame> {
            Ok(Self::encode_slice(std::slice::from_ref(self))?.into_dataframe())
        }

        /// # Errors
        /// Returns an error if schema construction or checked empty encoding
        /// fails.
        #[inline]
        fn empty_dataframe() -> PolarsResult<DataFrame> {
            Ok(Self::encode_slice(&[])?.into_dataframe())
        }

        /// # Errors
        /// Returns an error if explicit schema composition fails.
        #[inline]
        fn schema() -> PolarsResult<SchemaRef> {
            <Self as ColumnarSpec>::build_schema()
        }
    }

    impl<T: Columnar> ToDataFrame for T {}

    /// Extension trait enabling known-cardinality `.to_dataframe()` conversion
    /// on slices (and `Vec` via auto-deref).
    pub trait ToDataFrameVec {
        /// # Errors
        /// Returns an error if schema composition, value encoding, or batch
        /// validation fails.
        fn to_dataframe(&self) -> PolarsResult<DataFrame>;
    }

    impl<T> ToDataFrameVec for [T]
    where
        T: Columnar,
    {
        #[inline]
        fn to_dataframe(&self) -> PolarsResult<DataFrame> {
            Ok(<T as Columnar>::encode_slice(self)?.into_dataframe())
        }
    }

    // Unit-type support for generic payloads such as `Wrapper<()>`. Direct
    // derived fields of type `()` are rejected by df-derive, but a generic
    // field instantiated as `()` contributes zero columns while the checked
    // iterator boundary preserves the batch height.
    impl ColumnarSpec for () {
        #[inline]
        fn build_schema() -> PolarsResult<SchemaRef> {
            Ok(Arc::new(Schema::default()))
        }

        #[inline]
        fn encode_columns<'a, I>(_rows: &mut I, _sink: &mut ColumnSink) -> PolarsResult<()>
        where
            Self: 'a,
            I: RowCursor<Item = &'a Self>,
        {
            Ok(())
        }
    }

    /// Plug-in trait for converting a decimal value into its `i128`
    /// mantissa rescaled to a target scale.
    ///
    /// Implementers MUST use round-half-to-even (banker's rounding) on
    /// scale-down so the bytes the derive emits match polars's own
    /// `str_to_dec128` path. A `None` return surfaces as a polars
    /// `ComputeError` from the generated code.
    ///
    /// The codegen invokes this method through UFCS on the selected trait
    /// path, so inherent methods with the same name cannot bypass this
    /// contract. Custom backends (`bigdecimal::BigDecimal`,
    /// arbitrary-precision types, …) provide their own impls; this crate
    /// ships a `rust_decimal::Decimal` impl below.
    pub trait Decimal128Encode {
        /// Returns the mantissa as `i128` after rescaling `self` to
        /// `target_scale`, or `None` if the conversion would overflow or
        /// otherwise violate the schema. Implementations MUST round
        /// half-to-even on scale-down.
        fn try_to_i128_mantissa(&self, target_scale: u32) -> Option<i128>;
    }

    impl<T> Decimal128Encode for &T
    where
        T: Decimal128Encode + ?Sized,
    {
        #[inline]
        fn try_to_i128_mantissa(&self, target_scale: u32) -> Option<i128> {
            <T as Decimal128Encode>::try_to_i128_mantissa(*self, target_scale)
        }
    }

    /// Reference [`Decimal128Encode`] impl for [`rust_decimal::Decimal`].
    ///
    /// Banker's-rounding contract: round-half-to-even on scale-down,
    /// `checked_mul` overflow-to-`None` on scale-up. This impl is verified
    /// against polars's `str_to_dec128` on a battery of inputs covering
    /// half-tie boundaries (positive and negative), large magnitudes, and
    /// scale-up overflow by this repository's `df-derive-core` integration
    /// tests.
    #[cfg(feature = "rust_decimal")]
    impl Decimal128Encode for rust_decimal::Decimal {
        #[inline]
        fn try_to_i128_mantissa(&self, target_scale: u32) -> Option<i128> {
            // Bounds: `rust_decimal::Decimal::scale()` is capped at 28,
            // polars caps decimal scale at `DECIMAL128_MAX_SCALE`, so the
            // scale-up `diff` is at most 38 and the scale-down `diff` is at
            // most 28.
            // `10i128.pow(diff)` therefore fits in i128 for either direction
            // (max `10^38 < 2^127`).
            if target_scale > DECIMAL128_MAX_SCALE {
                return None;
            }

            let source_scale = self.scale();
            let mantissa: i128 = self.mantissa();
            if source_scale == target_scale {
                return Some(mantissa);
            }
            if source_scale < target_scale {
                let diff = target_scale - source_scale;
                let pow = 10i128.pow(diff);
                return mantissa.checked_mul(pow);
            }
            // Scale-down with round-half-to-even on the unsigned magnitude,
            // then re-apply sign — matches polars's `div_128_pow10`
            // semantics. The `(abs / pow)` quotient cannot exceed `i128::MAX`
            // because `abs <= i128::MAX as u128` and `pow >= 1`, so the
            // `cast_signed` is value-preserving.
            let diff = source_scale - target_scale;
            let pow = 10i128.pow(diff).cast_unsigned();
            let neg = mantissa < 0;
            let abs = mantissa.unsigned_abs();
            let q = (abs / pow).cast_signed();
            let r = abs % pow;
            let half = pow / 2;
            let rounded = match r.cmp(&half) {
                ::std::cmp::Ordering::Greater => q + 1,
                ::std::cmp::Ordering::Less => q,
                ::std::cmp::Ordering::Equal => q + (q & 1),
            };
            Some(if neg { -rounded } else { rounded })
        }
    }

    #[cfg(test)]
    mod checked_runtime_tests {
        use std::cell::Cell;

        use polars::prelude::{DataType, NamedFrom, Series};

        use super::*;

        fn schema(fields: impl IntoIterator<Item = (&'static str, DataType)>) -> SchemaRef {
            Arc::new(
                fields
                    .into_iter()
                    .map(|(name, dtype)| (name.into(), dtype))
                    .collect(),
            )
        }

        fn assert_error_contains<T>(result: PolarsResult<T>, expected: &str) {
            let Err(error) = result else {
                panic!("expected error containing `{expected}`");
            };
            assert!(
                error.to_string().contains(expected),
                "unexpected error: {error}"
            );
        }

        struct ObservableSizeHint<'rows, 'observer, T> {
            inner: std::slice::Iter<'rows, T>,
            calls: &'observer Cell<usize>,
        }

        impl<'rows, T> Iterator for ObservableSizeHint<'rows, '_, T> {
            type Item = &'rows T;

            fn next(&mut self) -> Option<Self::Item> {
                self.inner.next()
            }

            fn size_hint(&self) -> (usize, Option<usize>) {
                self.calls.set(self.calls.get() + 1);
                self.inner.size_hint()
            }
        }

        struct Valid(i64);

        impl ColumnarSpec for Valid {
            fn build_schema() -> PolarsResult<SchemaRef> {
                Ok(schema([("value", DataType::Int64)]))
            }

            fn encode_columns<'a, I>(rows: &mut I, sink: &mut ColumnSink) -> PolarsResult<()>
            where
                Self: 'a,
                I: RowCursor<Item = &'a Self>,
            {
                let values: Vec<i64> = rows.map(|row| row.0).collect();
                let slot = sink.next_slot()?;
                let column = Series::new(slot.name().clone(), values);
                slot.commit(column.into())
            }
        }

        struct ConsumesOnlyOne(i64);

        impl ColumnarSpec for ConsumesOnlyOne {
            fn build_schema() -> PolarsResult<SchemaRef> {
                Ok(schema([("value", DataType::Int64)]))
            }

            fn encode_columns<'a, I>(rows: &mut I, sink: &mut ColumnSink) -> PolarsResult<()>
            where
                Self: 'a,
                I: RowCursor<Item = &'a Self>,
            {
                let values: Vec<i64> = rows.next().map(|row| row.0).into_iter().collect();
                let slot = sink.next_slot()?;
                let column = Series::new(slot.name().clone(), values);
                slot.commit(column.into())
            }
        }

        struct RejectsRows;

        impl ColumnarSpec for RejectsRows {
            fn build_schema() -> PolarsResult<SchemaRef> {
                Ok(schema([]))
            }

            fn encode_columns<'a, I>(_rows: &mut I, _sink: &mut ColumnSink) -> PolarsResult<()>
            where
                Self: 'a,
                I: RowCursor<Item = &'a Self>,
            {
                Err(polars_err!(ComputeError: "intentional encoder error"))
            }
        }

        struct Borrowed<'a>(&'a str);

        impl ColumnarSpec for Borrowed<'_> {
            fn build_schema() -> PolarsResult<SchemaRef> {
                Ok(schema([("value", DataType::String)]))
            }

            fn encode_columns<'a, I>(rows: &mut I, sink: &mut ColumnSink) -> PolarsResult<()>
            where
                Self: 'a,
                I: RowCursor<Item = &'a Self>,
            {
                let values: Vec<&str> = rows.map(|row| row.0).collect();
                let slot = sink.next_slot()?;
                let column = Series::new(slot.name().clone(), values);
                slot.commit(column.into())
            }
        }

        #[test]
        fn checked_batch_preserves_schema_columns_and_actual_height() -> PolarsResult<()> {
            let rows = [Valid(1), Valid(2), Valid(3)];
            let dataframe = Valid::encode_batch(&rows)?.into_dataframe();

            assert_eq!(dataframe.shape(), (3, 1));
            assert_eq!(dataframe.schema().get("value"), Some(&DataType::Int64));
            Ok(())
        }

        #[test]
        fn checked_boundary_drains_successful_partial_consumers_before_validating_height() {
            let rows = [ConsumesOnlyOne(1), ConsumesOnlyOne(2)];
            assert_error_contains(ConsumesOnlyOne::encode_batch(&rows), "returned height 1");

            let refs = [&rows[0], &rows[1]];
            assert_error_contains(
                ConsumesOnlyOne::encode_ref_batch(&refs),
                "returned height 1",
            );
        }

        #[test]
        fn checked_boundary_does_not_drain_after_encoder_error() {
            let yielded = Cell::new(0);
            let rows = [RejectsRows, RejectsRows];
            let inspected = rows.iter().inspect(|_| yielded.set(yielded.get() + 1));

            assert_error_contains(
                RejectsRows::encode_batch(inspected),
                "intentional encoder error",
            );
            assert_eq!(yielded.get(), 0);
        }

        #[test]
        fn slice_cursor_replays_the_yielded_prefix_without_buffering() {
            let rows = [10_i32, 20, 30];
            let mut cursor = SliceCursor::new(&rows);
            cursor.enable_replay(rows.len());

            assert_eq!(cursor.next(), Some(&10));
            assert_eq!(cursor.next(), Some(&20));
            assert_eq!(cursor.yielded(), 2);

            let replay: std::slice::Iter<'_, i32> = cursor.replay();
            assert_eq!(replay.copied().collect::<Vec<_>>(), [10, 20]);
        }

        #[test]
        fn reference_slice_cursor_replays_original_row_references() {
            let rows = [10_i32, 20, 30];
            let refs = [&rows[0], &rows[1], &rows[2]];
            let mut cursor = RefSliceCursor::new(&refs);
            cursor.enable_replay(refs.len());

            assert_eq!(cursor.next(), Some(&10));
            assert_eq!(cursor.next(), Some(&20));
            assert_eq!(cursor.yielded(), 2);

            let replay: std::iter::Copied<std::slice::Iter<'_, &'_ i32>> = cursor.replay();
            assert_eq!(replay.copied().collect::<Vec<_>>(), [10, 20]);
        }

        #[test]
        fn streaming_cursor_observes_size_hint_once_and_counts_yielded_rows() {
            let rows = [10_i32, 20, 30];
            let size_hint_calls = Cell::new(0);
            let source = ObservableSizeHint {
                inner: rows.iter(),
                calls: &size_hint_calls,
            };
            let mut cursor = StreamingCursor::new(source);

            let (capacity, upper_bound) = cursor.size_hint();
            assert_eq!((capacity, upper_bound), (rows.len(), Some(rows.len())));
            cursor.by_ref().for_each(drop);

            assert_eq!(size_hint_calls.get(), 1);
            assert_eq!(cursor.yielded(), rows.len());
            let replay: std::iter::Empty<&i32> = cursor.replay();
            assert_eq!(replay.count(), 0);
        }

        #[test]
        fn replay_streaming_cursor_observes_size_hint_once_and_replays_yielded_rows() {
            let rows = [10_i32, 20, 30];
            let size_hint_calls = Cell::new(0);
            let source = ObservableSizeHint {
                inner: rows.iter(),
                calls: &size_hint_calls,
            };
            let mut cursor = ReplayStreamingCursor::new(source);

            let (capacity, upper_bound) = cursor.size_hint();
            assert_eq!((capacity, upper_bound), (rows.len(), Some(rows.len())));
            cursor.enable_replay(capacity);
            cursor.by_ref().for_each(drop);

            assert_eq!(size_hint_calls.get(), 1);
            assert_eq!(cursor.yielded(), rows.len());
            let replay: std::iter::Copied<std::slice::Iter<'_, &'_ i32>> = cursor.replay();
            assert_eq!(replay.copied().collect::<Vec<_>>(), rows);
        }

        #[test]
        #[should_panic(expected = "row replay must be enabled before iteration")]
        fn replay_streaming_cursor_rejects_late_enablement() {
            let rows = [10_i32, 20];
            let mut cursor = ReplayStreamingCursor::new(rows.iter());

            assert_eq!(cursor.next(), Some(&10));
            assert_eq!(cursor.yielded(), 1);
            cursor.enable_replay(rows.len());
        }

        #[test]
        fn sink_slots_reject_extra_reordered_mistyped_and_missing_columns() -> PolarsResult<()> {
            let expected = schema([("value", DataType::Int64)]);

            let mut reordered = ColumnSink::new(expected.clone(), "Reordered");
            let slot = reordered.next_slot()?;
            assert_error_contains(
                slot.commit(Series::new("other".into(), [1_i64]).into()),
                "returned column `other`",
            );
            assert_eq!(reordered.columns.len(), 0);

            let mut mistyped = ColumnSink::new(expected.clone(), "Mistyped");
            let slot = mistyped.next_slot()?;
            assert_error_contains(
                slot.commit(Series::new("value".into(), ["wrong"]).into()),
                "returned dtype",
            );
            assert_eq!(mistyped.columns.len(), 0);

            let mut extra = ColumnSink::new(expected.clone(), "Extra");
            let slot = extra.next_slot()?;
            assert_eq!(slot.name().as_str(), "value");
            assert_eq!(slot.dtype(), &DataType::Int64);
            slot.commit(Series::new("value".into(), [1_i64]).into())?;
            assert_error_contains(extra.next_slot(), "schema width 1");

            let missing = ColumnSink::new(expected, "Missing");
            assert_error_contains(missing.finish(1), "returned schema width 0");
            Ok(())
        }

        #[test]
        fn failed_slot_commit_can_retry_the_same_schema_position() -> PolarsResult<()> {
            let expected = schema([("value", DataType::Int64)]);
            let mut sink = ColumnSink::new(expected, "Retry");

            let dropped = sink.next_slot()?;
            assert_eq!(dropped.name().as_str(), "value");
            drop(dropped);

            let slot = sink.next_slot()?;
            assert_error_contains(
                slot.commit(Series::new("wrong".into(), [1_i64]).into()),
                "expected `value`",
            );

            let slot = sink.next_slot()?;
            assert_error_contains(
                slot.commit(Series::new("value".into(), ["wrong dtype"]).into()),
                "returned dtype",
            );

            let slot = sink.next_slot()?;
            assert_eq!(slot.name().as_str(), "value");
            let column = Series::new(slot.name().clone(), [1_i64]);
            slot.commit(column.into())?;
            sink.finish(1)?;
            Ok(())
        }

        #[test]
        fn borrowed_models_do_not_require_static_lifetimes() -> PolarsResult<()> {
            let owned = [String::from("one"), String::from("two")];
            let rows = [Borrowed(&owned[0]), Borrowed(&owned[1])];
            let dataframe = Borrowed::encode(&rows)?;

            assert_eq!(dataframe.shape(), (2, 1));
            Ok(())
        }

        #[test]
        fn unit_batches_preserve_height_without_columns() -> PolarsResult<()> {
            let rows = [(), (), ()];
            let dataframe = <() as Columnar>::encode_batch(&rows)?.into_dataframe();

            assert_eq!(dataframe.shape(), (3, 0));
            Ok(())
        }
    }
}
